const $=(s,e=document)=>e.querySelector(s), $$=(s,e=document)=>[...e.querySelectorAll(s)];
const state={companies:[],customers:[],items:[],invoices:[],estimates:[],domains:[],settings:{},page:'dashboard'};
$('nav button[data-page="items"]').insertAdjacentHTML('afterend','<button data-page="domains"><i>◎</i><b>Domains</b></button>');
const api=async(url,opts={})=>{const r=await fetch('/api'+url,{headers:{'Content-Type':'application/json'},...opts,body:opts.body?JSON.stringify(opts.body):undefined}),text=r.status===204?'':await r.text();let data={};if(text){try{data=JSON.parse(text)}catch{throw Error(r.ok?'Server returned an invalid response':'Request was not handled by the online API. Please deploy the latest server.js and restart Node.')}}if(!r.ok)throw Error(data.error||'Something went wrong');return data};
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const descriptionBullets=value=>{const val=String(value||'').trim();if(!val)return '';if(/<[a-z][\s\S]*>/i.test(val)){return `<div class="item-description item-description-rich">${val}</div>`}const points=val.replace(/\r/g,'').split('\n').map(point=>point.trim().replace(/^(?:[•●▪◦*-]|\d+[.)])\s*/,'')).filter(Boolean);return points.length?`<ul class="item-description">${points.map(point=>`<li>${esc(point)}</li>`).join('')}</ul>`:''};
const formatItemDescriptions=()=>$$('.paper-table td small').forEach(node=>{const raw=node.innerHTML||node.textContent||'';const html=descriptionBullets(raw);if(html)node.outerHTML=html;else node.remove()});
function attachRichTextEditor(textarea,placeholder='Type description...'){if(!textarea||textarea.dataset.rteInitialized)return;textarea.dataset.rteInitialized='true';textarea.setAttribute('hidden','true');textarea.style.setProperty('display','none','important');const container=document.createElement('div');container.className='rte-container';container.innerHTML=`<div class="rte-toolbar"><div class="rte-group"><button type="button" class="rte-btn" data-cmd="bold" title="Bold (Ctrl+B)"><b>B</b></button><button type="button" class="rte-btn" data-cmd="italic" title="Italic (Ctrl+I)"><i>I</i></button><button type="button" class="rte-btn" data-cmd="underline" title="Underline (Ctrl+U)"><u>U</u></button></div><div class="rte-separator"></div><div class="rte-group"><button type="button" class="rte-btn" data-cmd="insertUnorderedList" title="Bullet List">• List</button><button type="button" class="rte-btn" data-cmd="insertOrderedList" title="Numbered List">1. List</button></div><div class="rte-separator"></div><div class="rte-group"><button type="button" class="rte-btn rte-btn-badge" data-action="add-bullet" title="Quick Bullet Points">+ Bullet</button><button type="button" class="rte-btn" data-cmd="removeFormat" title="Clear Formatting">🧹</button></div></div><div class="rte-editor" contenteditable="true" data-placeholder="${esc(placeholder)}"></div>`;textarea.parentNode.insertBefore(container,textarea);container.appendChild(textarea);const editor=container.querySelector('.rte-editor');const setContent=val=>{const raw=String(val||'').trim();if(!raw){editor.innerHTML='';textarea.value='';return}if(/<[a-z][\s\S]*>/i.test(raw)){editor.innerHTML=raw}else{const lines=raw.split('\n').map(l=>l.trim()).filter(Boolean);editor.innerHTML=lines.length?`<ul>${lines.map(l=>`<li>${esc(l.replace(/^(?:[•●▪◦*-]|\d+[.)])\s*/,''))}</li>`).join('')}</ul>`:''}textarea.value=editor.innerHTML.trim()};setContent(textarea.value);const sync=()=>{let html=editor.innerHTML.trim();if(html==='<br>'||html==='<div><br></div>'||html==='<p><br></p>')html='';textarea.value=html};textarea.syncRte=setContent;editor.addEventListener('input',sync);editor.addEventListener('blur',sync);editor.addEventListener('keyup',()=>{updateStates();sync()});editor.addEventListener('mouseup',updateStates);function updateStates(){container.querySelectorAll('[data-cmd]').forEach(btn=>{const cmd=btn.dataset.cmd;try{btn.classList.toggle('active',document.queryCommandState(cmd))}catch(e){}})}container.querySelectorAll('.rte-btn').forEach(btn=>{btn.addEventListener('mousedown',e=>{e.preventDefault();const cmd=btn.dataset.cmd,action=btn.dataset.action;if(cmd){document.execCommand(cmd,false,null);updateStates();sync()}else if(action==='add-bullet'){editor.focus();document.execCommand('insertUnorderedList',false,null);updateStates();sync()}})});}
const addInvoiceReminderAction=()=>{const del=$('[data-invoice-delete]');if(del&&!$('#overdueReminder'))del.insertAdjacentHTML('beforebegin',`<button class="secondary" id="overdueReminder" data-invoice-id="${del.dataset.invoiceDelete}">Send overdue reminder</button>`)};
const toast=s=>{const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)};
const today=()=>new Date().toISOString().slice(0,10), later=(days=7)=>{const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)};
function applyBrand(){const name=String(state.settings.crm_name||'BillFlow').trim()||'BillFlow',authBrand=$('.auth .brand'),sidebarBrand=$('aside .brand>div');if(authBrand?.lastChild)authBrand.lastChild.nodeValue=' '+name;if(sidebarBrand?.firstChild)sidebarBrand.firstChild.nodeValue=name;document.title=`${name} CRM`}
const modal=(html,wide=false)=>{$('#modalContent').innerHTML=html;$('.dialog').classList.toggle('wide',wide);$('#modal').hidden=false;formatItemDescriptions();addInvoiceReminderAction();$$('#modalContent textarea[name="description"]').forEach(ta=>attachRichTextEditor(ta,'Enter item description, specifications, bullet points...'));const status=$('#estimateStatus');if(status&&!status.querySelector('[value="done"]')){status.add(new Option('Done','done'));status.add(new Option('Cancelled','cancelled'))}};
const close=()=>{$('#modal').hidden=true};
document.addEventListener('click',async e=>{if(e.target.matches('[data-close]')||e.target===$('#modal'))close();const del=e.target.closest?.('[data-invoice-delete]');if(del){if(!confirm('Delete this invoice permanently? Payment records will remain in the customer ledger.'))return;try{await api('/invoices/delete',{method:'POST',body:{id:Number(del.dataset.invoiceDelete)}});close();await loadAll();if(state.page==='dashboard')dashboard();else show('invoices');toast('Invoice deleted')}catch(err){toast(err.message)}}});
document.addEventListener('click',async e=>{const button=e.target.closest?.('#downloadPdf');if(!button)return;e.preventDefault();e.stopImmediatePropagation();const id=$('.sendbar [data-invoice-delete]')?.dataset.invoiceDelete;if(!id)return toast('Invoice not found');button.disabled=true;try{const response=await fetch(`/api/invoices/${id}/pdf`),type=response.headers.get('content-type')||'';if(!response.ok||!type.includes('application/pdf')){let message='Could not generate invoice PDF';try{message=(await response.json()).error||message}catch{}throw new Error(message)}const blob=await response.blob(),disposition=response.headers.get('content-disposition')||'',match=disposition.match(/filename="([^"]+)"/i),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=match?.[1]||'Invoice.pdf';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),1000);toast('Invoice PDF downloaded')}catch(error){toast(error.message)}finally{button.disabled=false}},true);
document.addEventListener('click',async e=>{const button=e.target.closest?.('#overdueReminder');if(!button)return;button.disabled=true;try{await api(`/invoices/${button.dataset.invoiceId}/overdue-reminder`,{method:'POST'});toast('Overdue payment reminder sent on WhatsApp');await loadAll()}catch(error){toast(error.message)}finally{button.disabled=false}});

async function init(){const setup=await api('/setup-status');$('#authTitle').textContent=setup.needsSetup?'Create your admin account':'Welcome back';$('#authText').textContent=setup.needsSetup?'Set up your Invoice CRM':'Sign in to manage your business';$('#nameField').hidden=!setup.needsSetup;$('#authForm').dataset.setup=setup.needsSetup;try{const me=await api('/me');enter(me)}catch{}}
$('#authForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{const me=await api(e.target.dataset.setup==='true'?'/setup':'/login',{method:'POST',body:f});enter(me)}catch(x){$('#authError').textContent=x.message}};
async function enter(me){$('#auth').hidden=true;$('#app').hidden=false;$('#userName').textContent=me.name;$('#avatar').textContent=me.name[0].toUpperCase();await loadAll();show('dashboard')}
$('#logout').onclick=async()=>{await api('/logout',{method:'POST'});location.reload()};const closeSidebar=()=>$('aside').classList.remove('open');$('#menu').onclick=()=>$('aside').classList.add('open');$('#sidebarClose').onclick=$('#sidebarBackdrop').onclick=closeSidebar;
$$('nav button').forEach(b=>b.onclick=()=>show(b.dataset.page));$('#headerAction').onclick=()=>invoicePage();
async function loadAll(){[state.companies,state.customers,state.items,state.invoices,state.estimates,state.domains,state.settings]=await Promise.all(['/companies','/customers','/items','/invoices','/estimates','/domains','/settings'].map(api));applyBrand()}
const titles={dashboard:['Dashboard','Your business at a glance'],invoices:['Invoices','Create, send and track invoices'],estimates:['Estimates','Create, download and send estimates'],domains:['Domains','Track client domains and yearly renewals'],ledger:['Customer ledger','Track payments, pending balances and reminders'],followups:['Follow-ups','Schedule and send customer WhatsApp follow-ups'],automations:['WhatsApp Automations','Create Meta templates and assign them to CRM events'],reports:['Reports','Invoice, payment, client and GST tax reporting'],customers:['Customers','Manage your customer directory'],items:['Items & Services','Your reusable product catalogue'],companies:['Companies','Manage the businesses you invoice from'],settings:['Settings','Configure communication integrations']};
async function show(page){state.page=page;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#pageTitle').textContent=titles[page][0];$('#pageHint').textContent=titles[page][1];$('#headerAction').style.display=['settings','ledger','reports','automations'].includes(page)?'none':'';$('#headerAction').textContent=page==='customers'?'＋ Add customer':page==='items'?'＋ Add item':page==='companies'?'＋ Add company':page==='domains'?'＋ Add domain':page==='estimates'?'＋ New estimate':page==='followups'?'＋ New follow-up':'＋ New invoice';$('#headerAction').onclick=()=>page==='customers'?resourceForm('customers'):page==='items'?resourceForm('items'):page==='companies'?resourceForm('companies'):page==='domains'?domainForm():page==='estimates'?estimatePage():page==='followups'?followupForm():invoicePage();$('aside').classList.remove('open');await render();if(page==='dashboard')await dashboardFollowups()}
async function render(){if(state.page==='dashboard'){await dashboard();return dashboardDomainRenewals()}if(state.page==='settings'){await settings();addAutomationSettings();return}if(state.page==='automations')return automationsPage();if(state.page==='domains')return domainsPage();if(state.page==='ledger')return ledgerPage();if(state.page==='estimates')return estimatesPage();if(state.page==='followups')return followupsPage();if(state.page==='reports')return reportsPage();return listPage(state.page)}
function addAutomationSettings(){const panels=$$('.panel','#settingsForm'),target=panels.find(p=>$('h3',p)?.textContent==='Automatic estimate follow-up');if(target){const grid=$('.form-grid',target);grid.insertAdjacentHTML('beforeend',`<label>Daily WhatsApp time<select name="followup_send_hour">${Array.from({length:24},(_,h)=>`<option value="${h}" ${Number(state.settings.followup_send_hour||10)===h?'selected':''}>${String(h).padStart(2,'0')}:00</option>`).join('')}</select></label><label class="switch automation-switch"><input type="checkbox" id="autoFollowups" ${state.settings.auto_followups!=='false'?'checked':''}><span><b>Automatic daily messages</b><small>One message per day until estimate is closed</small></span></label><input type="hidden" name="auto_followups" id="autoFollowupsValue" value="${state.settings.auto_followups==='false'?'false':'true'}">`);$('#autoFollowups').onchange=e=>$('#autoFollowupsValue').value=e.target.checked?'true':'false'}const meta=panels.find(p=>$('h3',p)?.textContent==='Meta WhatsApp Cloud API');if(meta)$('.form-grid',meta).insertAdjacentHTML('afterbegin',field('WhatsApp Business Account ID (WABA ID)','meta_waba_id',state.settings.meta_waba_id))}
async function dashboard(){const d=await api('/dashboard'),months=[];for(let i=5;i>=0;i--){const date=new Date();date.setMonth(date.getMonth()-i);months.push(date.toISOString().slice(0,7))}const inv=Object.fromEntries(d.monthlyInvoices.map(x=>[x.month,x.amount])),pay=Object.fromEntries(d.monthlyPayments.map(x=>[x.month,x.amount])),max=Math.max(1,...months.flatMap(m=>[inv[m]||0,pay[m]||0])),statusTotal=d.statuses.reduce((s,x)=>s+x.count,0)||1,colors={draft:'#7c8aa5',sent:'#2962ea',paid:'#14a673',overdue:'#ef704f',cancelled:'#9aa3b2'},segments=[];let cursor=0;for(const x of d.statuses){const end=cursor+x.count/statusTotal*100;segments.push(`${colors[x.status]||'#8b5cf6'} ${cursor}% ${end}%`);cursor=end}$('#content').innerHTML=`<div class="dashboard-kpis"><div class="color-card blue"><span>₹</span><p>Total invoiced</p><h3>${money(d.revenue)}</h3><small>${d.invoices} invoices</small></div><div class="color-card green"><span>✓</span><p>Payments received</p><h3>${money(d.paid)}</h3><small>${d.revenue?Math.round(d.paid/d.revenue*100):0}% collected</small></div><div class="color-card orange"><span>◷</span><p>Pending amount</p><h3>${money(d.pending)}</h3><small>Needs follow-up</small></div><div class="color-card purple"><span>♙</span><p>Total customers</p><h3>${d.customers}</h3><small>${d.companies} companies</small></div></div><div class="dashboard-grid"><div class="panel chart-panel"><div class="panel-head"><div><h3>Business performance</h3><p>Invoices and payments over 6 months</p></div><div class="chart-legend"><span class="invoice-dot">Invoiced</span><span class="payment-dot">Received</span></div></div><div class="bar-chart">${months.map(m=>`<div class="bar-group"><div class="bars"><i class="bar invoiced" style="height:${(inv[m]||0)/max*100}%" title="Invoiced ${money(inv[m]||0)}"></i><i class="bar received" style="height:${(pay[m]||0)/max*100}%" title="Received ${money(pay[m]||0)}"></i></div><small>${new Date(m+'-01').toLocaleString('en',{month:'short'})}</small></div>`).join('')}</div></div><div class="panel status-panel"><div class="panel-head"><div><h3>Invoice status</h3><p>${statusTotal} total invoices</p></div></div><div class="donut-wrap"><div class="donut" style="background:conic-gradient(${segments.join(',')||'#e5e7eb 0 100%'})"><div><b>${statusTotal}</b><small>Invoices</small></div></div><div class="status-legend">${d.statuses.map(x=>`<div><i style="background:${colors[x.status]||'#8b5cf6'}"></i><span>${esc(x.status)}</span><b>${x.count}</b></div>`).join('')}</div></div></div></div><div class="panel"><div class="panel-head"><h3>Recent invoices</h3><button class="link" data-view-all>View all</button></div>${invoiceTable(d.recent)}</div>`;$('[data-view-all]').onclick=()=>show('invoices')}

async function dashboardDomainRenewals(){const data=await api('/domain-renewals'),anchor=$('.dashboard-grid');if(!anchor||state.page!=='dashboard'||!data.length)return;const section=document.createElement('div');section.className='panel domain-renewal-panel';section.innerHTML=`<div class="panel-head"><div><h3>🌐 Domain renewals</h3><p>${data.filter(x=>x.days_left<0).length} overdue · ${data.filter(x=>x.days_left>=0).length} due in 60 days</p></div><button class="link" id="viewDomains">View all</button></div><div class="renewal-strip">${data.slice(0,6).map(x=>`<article class="renewal-card ${x.days_left<0?'expired':x.days_left<=15?'urgent':''}"><div><b>${esc(x.domain_name)}</b><small>${esc(x.business_name||x.customer)}</small></div><span>${x.days_left<0?Math.abs(x.days_left)+' days overdue':x.days_left===0?'Due today':x.days_left+' days left'}</span><time>${esc(x.renewal_date)}</time></article>`).join('')}</div>`;anchor.before(section);$('#viewDomains').onclick=()=>show('domains')}
function domainStatus(x){if(x.status!=='active')return x.status;if(x.days_left<0)return'expired';if(x.days_left<=15)return'urgent';if(x.days_left<=60)return'upcoming';return'active'}
function domainsPage(){const rowsHtml=state.domains.length?state.domains.map(x=>{const status=domainStatus(x);return `<tr><td><b>${esc(x.domain_name)}</b><small>${esc(x.registrar||'Registrar not set')}</small></td><td>${esc(x.business_name||x.customer)}</td><td>${esc(x.renewal_date)}</td><td>${money(x.yearly_cost)}</td><td><span class="badge domain-${status}">${status}</span>${x.auto_renew?'<small class="auto-renew">Auto-renew</small>':''}</td><td class="actions"><button data-domain-remind="${x.id}">WhatsApp</button><button data-domain-edit="${x.id}">Edit</button><button class="danger-link" data-domain-delete="${x.id}">Delete</button></td></tr>`}).join(''):'<tr><td colspan="6" class="empty">No domains added yet.</td></tr>';$('#content').innerHTML=`<div class="domain-summary"><div><b>${state.domains.length}</b><span>Total domains</span></div><div><b>${state.domains.filter(x=>x.status==='active'&&x.days_left<0).length}</b><span>Overdue</span></div><div><b>${state.domains.filter(x=>x.status==='active'&&x.days_left>=0&&x.days_left<=30).length}</b><span>Due in 30 days</span></div><div><b>${money(state.domains.reduce((sum,x)=>sum+Number(x.yearly_cost||0),0))}</b><span>Annual renewal value</span></div></div><div class="panel"><div class="toolbar"><input id="domainSearch" placeholder="Search domain or client..."><span>${state.domains.length} total</span></div><div class="table-wrap"><table class="domain-table"><thead><tr><th>Domain</th><th>Client</th><th>Renewal date</th><th>Yearly cost</th><th>Status</th><th></th></tr></thead><tbody>${rowsHtml}</tbody></table></div></div>`;$('#domainSearch').oninput=e=>$$('.domain-table tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase()));$$('[data-domain-edit]').forEach(b=>b.onclick=()=>domainForm(state.domains.find(x=>x.id==b.dataset.domainEdit)));$$('[data-domain-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this domain record?'))return;await api('/domains/'+b.dataset.domainDelete,{method:'DELETE'});await loadAll();domainsPage();toast('Domain deleted')});$$('[data-domain-remind]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api(`/domains/${b.dataset.domainRemind}/reminder`,{method:'POST'});toast('Domain renewal reminder sent on WhatsApp')}catch(e){toast(e.message)}finally{b.disabled=false}})}
function domainForm(x={}){modal(`<h2>${x.id?'Edit':'Add'} domain</h2><form id="domainForm"><div class="form-grid"><label>Client *<select name="customer_id" required><option value="">Select client</option>${state.customers.map(c=>`<option value="${c.id}" ${c.id===x.customer_id?'selected':''}>${esc(c.business_name||c.name)}</option>`).join('')}</select></label>${field('Domain name *','domain_name',x.domain_name,'text','required placeholder="example.com"')}${field('Registrar','registrar',x.registrar,'text','placeholder="GoDaddy, Namecheap, Hostinger..."')}${field('Purchase date','purchase_date',x.purchase_date,'date')}${field('Renewal date *','renewal_date',x.renewal_date,'date','required')}${field('Yearly renewal cost','yearly_cost',x.yearly_cost||0,'number','min="0" step="0.01"')}<label>Status<select name="status"><option value="active" ${x.status!=='inactive'?'selected':''}>Active</option><option value="inactive" ${x.status==='inactive'?'selected':''}>Inactive</option></select></label><label class="switch domain-auto"><input type="checkbox" name="auto_renew" value="1" ${x.auto_renew?'checked':''}><span><b>Auto-renew enabled</b><small>Registrar renews this domain automatically</small></span></label><label class="full">Notes<textarea name="notes" rows="4">${esc(x.notes)}</textarea></label></div><div class="form-actions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary">Save domain</button></div></form>`);$('#domainForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.customer_id=Number(b.customer_id);b.yearly_cost=Number(b.yearly_cost||0);b.auto_renew=Boolean(b.auto_renew);await api(x.id?'/domains/'+x.id:'/domains',{method:x.id?'PUT':'POST',body:b});await loadAll();close();domainsPage();toast('Domain saved')}}
async function dashboardFollowups(){const d=await api('/dashboard'),anchor=$('.dashboard-grid');if(!anchor||state.page!=='dashboard')return;const section=document.createElement('div');section.className='panel dashboard-followups';section.innerHTML=`<div class="panel-head"><div><h3><span class="followup-pulse"></span>Important follow-ups</h3><p>${d.dueFollowups} due or overdue · ${d.followups.length} upcoming</p></div><button class="link" id="viewFollowups">View all</button></div>${d.followups.length?`<div class="followup-strip">${d.followups.map(x=>{const due=x.followup_date<=today();return `<article class="followup-card ${due?'due':''}"><div class="followup-date"><b>${new Date(x.followup_date+'T00:00:00').getDate()}</b><small>${new Date(x.followup_date+'T00:00:00').toLocaleString('en',{month:'short'})}</small></div><div class="followup-content"><b>${esc(x.business_name||x.customer)}</b><small>${x.estimate_number?'Estimate '+esc(x.estimate_number):'General follow-up'}</small><p>${esc(x.message)}</p></div><div class="followup-quick"><button class="primary" data-dash-send="${x.id}">WhatsApp</button><button class="secondary" data-dash-done="${x.id}">Done</button></div></article>`}).join('')}</div>`:'<div class="followup-clear"><span>✓</span><div><b>All caught up!</b><p>No pending customer follow-ups.</p></div></div>'}`;anchor.before(section);$('#viewFollowups').onclick=()=>show('followups');$$('[data-dash-send]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api(`/followups/${b.dataset.dashSend}/send`,{method:'POST'});toast('Follow-up sent on WhatsApp');await show('dashboard')}catch(err){toast(err.message)}finally{b.disabled=false}});$$('[data-dash-done]').forEach(b=>b.onclick=async()=>{await api('/followups/'+b.dataset.dashDone,{method:'PATCH',body:{status:'completed'}});toast('Follow-up completed');await show('dashboard')})}
function invoiceTable(data){if(!data.length)return '<div class="empty">No invoices yet. Create your first invoice.</div>';return `<div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Company</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${data.map(x=>`<tr><td><b>${esc(x.number)}</b></td><td>${esc(x.customer)}</td><td>${esc(x.company)}</td><td>${esc(x.invoice_date)}</td><td><b>${money(x.total)}</b></td><td><span class="badge ${x.status}">${x.status}</span></td><td class="actions invoice-list-actions"><button data-preview="${x.id}">View</button><button class="danger-link" data-invoice-delete="${x.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`}
function listPage(type){let html='';if(type==='invoices')html=invoiceTable(state.invoices);else {const data=state[type];const heads=type==='customers'?['Name','Company','Phone','GSTIN']:type==='items'?['Name','Code','Unit','Price']:['Company','GSTIN','Email','Phone'];html=data.length?`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}<th></th></tr></thead><tbody>${data.map(x=>{const vals=type==='customers'?[x.name,state.companies.find(c=>c.id===x.company_id)?.name,x.phone,x.gstin]:type==='items'?[x.name,x.code,x.unit,money(x.price)]:[x.name,x.gstin,x.email,x.phone];return `<tr>${vals.map((v,i)=>`<td>${i===0?'<b>'+esc(v||'—')+'</b>':esc(v||'—')}</td>`).join('')}<td class="actions"><button data-edit="${x.id}">Edit</button><button data-delete="${x.id}">Delete</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Nothing here yet. Use the button above to add one.</div>'}$('#content').innerHTML=`<div class="panel"><div class="toolbar"><input id="search" placeholder="Search ${type}..."><span>${state[type].length} total</span></div><div id="list">${html}</div></div>`;$$('[data-preview]').forEach(b=>b.onclick=()=>preview(b.dataset.preview));$$('[data-edit]').forEach(b=>b.onclick=()=>resourceForm(type,state[type].find(x=>x.id==b.dataset.edit)));$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this record?')){try{await api(`/${type}/delete`,{method:'POST',body:{id:Number(b.dataset.delete)}});await loadAll();render();toast('Deleted')}catch(e){toast(e.message)}}});const search=$('#search');if(search)search.oninput=()=>$$('#list tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(search.value.toLowerCase()))}

const field=(label,name,value='',type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const fileData=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});
function resourceForm(type,x={}){let fields='';if(type==='companies')fields=field('Company name *','name',x.name,'text','required')+field('GSTIN (optional)','gstin',x.gstin)+field('Email','email',x.email,'email')+field('Phone','phone',x.phone)+`<label class="full">Address<textarea name="address">${esc(x.address)}</textarea></label>`+field('Invoice prefix','invoice_prefix',x.invoice_prefix||'INV')+`<label>Company logo<div class="logo-upload"><input name="logo_file" type="file" accept="image/png,image/jpeg,image/webp"><span>PNG, JPG or WebP</span></div>${x.logo?`<img id="companyLogoPreview" class="company-logo-preview" src="${esc(x.logo)}">`:''}</label><label class="full">Bank details<textarea name="bank_details">${esc(x.bank_details)}</textarea></label>`;if(type==='customers')fields=`<label>Under your company *<select name="company_id" required><option value="">Select company</option>${state.companies.map(c=>`<option value="${c.id}" ${c.id===x.company_id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`+field('Customer name *','name',x.name,'text','required')+field('Business name','business_name',x.business_name)+field('GSTIN (optional)','gstin',x.gstin)+field('Email','email',x.email,'email')+field('Phone / WhatsApp','phone',x.phone)+`<label class="full">Billing address<textarea name="address">${esc(x.address)}</textarea></label><label class="full">Notes<textarea name="notes">${esc(x.notes)}</textarea></label>`;if(type==='items')fields=field('Item / service name *','name',x.name,'text','required')+field('Product code','code',x.code)+field('Price','price',x.price||0,'number','min="0" step="0.01"')+field('Unit','unit',x.unit||'unit')+`<label class="full">Description<textarea name="description">${esc(x.description)}</textarea></label>`;modal(`<h2>${x.id?'Edit':'Add'} ${type.slice(0,-1)}</h2><form id="resourceForm"><div class="form-grid">${fields}</div><div class="form-actions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary">Save</button></div></form>`);const resDescTextarea=$('[name="description"]','#resourceForm');if(resDescTextarea)attachRichTextEditor(resDescTextarea,'Enter item description, specifications, bullet points...');const logoInput=$('[name="logo_file"]');if(logoInput)logoInput.onchange=async me=>{if(logoInput.files[0]){const src=await fileData(logoInput.files[0]);let preview=$('#companyLogoPreview');if(!preview){preview=document.createElement('img');preview.id='companyLogoPreview';preview.className='company-logo-preview';logoInput.closest('label').append(preview)}preview.src=src}};$('#resourceForm').onsubmit=async e=>{e.preventDefault();const formData=new FormData(e.target),logoFile=formData.get('logo_file');formData.delete('logo_file');const b=Object.fromEntries(formData);if(type==='companies')b.logo=logoFile?.size?await fileData(logoFile):(x.logo||'');for(const k of ['company_id','price'])if(k in b)b[k]=+b[k]||0;if(x.id)b.id=Number(x.id);try{await api(`/${type}${x.id?'/save':''}`,{method:'POST',body:b});await loadAll();close();render();toast('Saved successfully')}catch(err){toast(err.message)}}}

function invoicePage(){
  if(!state.companies.length){toast('Please add your company first');return show('companies')}
  state.page='create-invoice';$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page==='invoices'));
  $('#pageTitle').textContent='Create invoice';$('#pageHint').textContent='Build and preview a new invoice';$('#headerAction').style.display='none';
  $('#content').innerHTML=`<button class="secondary invoice-back" id="invoiceBack">‹ Back to invoices</button><form id="invoiceCreate" class="invoice-editor"><div class="invoice-editor-top"><div class="customer-picker"><label>Customer *<select name="customer_id" id="invoiceCustomer" required><option value="">Add customer</option>${state.customers.map(c=>`<option value="${c.id}">${esc(c.name)}${c.business_name?' — '+esc(c.business_name):''}</option>`).join('')}</select></label><button type="button" class="link" id="newCustomer">＋ New customer</button><div id="customerInfo" class="selected-info"></div></div><div class="invoice-fields">${field('Invoice date *','invoice_date',today(),'date','required')}${field('Due date','due_date',later(),'date')}${field('Purchase Order (PO) #','po_number')}</div></div><section class="invoice-lines-card"><div class="invoice-line-head"><b>ITEM</b><b>QUANTITY</b><b>PRICE</b><b>AMOUNT</b><span></span></div><div id="pageLines"></div><div class="invoice-add-row"><div><button type="button" class="secondary" id="addExisting">＋ Add item</button><button type="button" class="link" id="newItem">＋ New item</button></div><div class="editor-totals"><div><span>Subtotal</span><b id="pageSubtotal">₹0.00</b></div><div id="pageTaxRow" hidden><span>GST</span><b id="pageTax">₹0.00</b></div><div class="grand"><span>Total</span><b id="pageTotal">₹0.00</b></div><div class="amount-due"><span>Amount due</span><b id="amountDue">₹0.00</b></div></div></div></section><div class="gst-option"><label class="switch"><input type="checkbox" id="pageGst"><span><b>Apply GST</b><small>Calculate GST using each item's tax rate</small></span></label></div><label class="invoice-note">Note<textarea name="notes" rows="5" placeholder="Type your note here..."></textarea></label><div class="invoice-page-actions"><button type="button" class="secondary" id="cancelInvoice">Cancel</button><button class="primary">Create & preview</button></div></form>`;
  const lines=$('#pageLines');
  const gstRate=Number(state.settings.gst_rate||18);const calc=()=>{let sub=0;$$('.invoice-item-row',lines).forEach(r=>{const amount=+$('.qty',r).value*+$('.price',r).value;sub+=amount;$('.line-amount',r).textContent=money(amount)});const use=$('#pageGst').checked,tax=use?sub*gstRate/100:0;$('#pageSubtotal').textContent=money(sub);$('#pageTax').textContent=money(tax);$('#pageTaxRow').hidden=!use;$('#pageTotal').textContent=$('#amountDue').textContent=money(sub+tax)};
  const addLine=(selected)=>{const row=document.createElement('div');row.className='invoice-item-row';row.innerHTML=`<div class="item-main"><select class="item" required><option value="">Type your item to add</option>${state.items.map(i=>`<option value="${i.id}" ${selected?.id===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select><textarea class="description" rows="2" placeholder="Type description..."></textarea></div><input class="qty" type="number" min="0.01" step="0.01" value="1" required><input class="price" type="number" min="0" step="0.01" value="${selected?.price||0}" required><b class="line-amount">₹0.00</b><button type="button" class="remove-line" title="Remove">×</button>`;lines.append(row);const descTextarea=$('.description',row);attachRichTextEditor(descTextarea,'Type description...');const select=$('.item',row);const setItem=()=>{const it=state.items.find(i=>i.id==select.value);if(it){$('.price',row).value=it.price;if(descTextarea.syncRte)descTextarea.syncRte(it.description||'');else descTextarea.value=it.description||''}calc()};select.onchange=setItem;$$('input',row).forEach(i=>i.oninput=calc);$('.remove-line',row).onclick=()=>{row.remove();if(!$$('.invoice-item-row',lines).length)addLine();calc()};if(selected){if(descTextarea.syncRte)descTextarea.syncRte(selected.description||'');else descTextarea.value=selected.description||''}calc()};
  const quickForm=(type)=>{const isCustomer=type==='customer';modal(`<h2>New ${type}</h2><form id="quickForm"><div class="form-grid">${isCustomer?`<label>Under your company *<select name="company_id" required>${state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label>${field('Customer name *','name','','text','required')}${field('Business name','business_name')}${field('GSTIN (optional)','gstin')}${field('Email','email','','email')}${field('Phone / WhatsApp','phone')}<label class="full">Billing address<textarea name="address"></textarea></label>`:`${field('Item name *','name','','text','required')}${field('Product code','code')}${field('Price','price',0,'number','min="0" step="0.01"')}${field('Unit','unit','unit')}<label class="full">Description<textarea name="description" rows="4"></textarea></label>`}</div><div class="form-actions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary">Save</button></div></form>`);const quickDescTextarea=$('[name="description"]','#quickForm');if(quickDescTextarea)attachRichTextEditor(quickDescTextarea,'Enter item description, specifications, bullet points...');$('#quickForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));for(const k of ['company_id','price'])if(k in b)b[k]=+b[k]||0;try{const saved=await api(isCustomer?'/customers':'/items',{method:'POST',body:b});if(isCustomer){state.customers.unshift(saved);const option=new Option(saved.name,saved.id,true,true);$('#invoiceCustomer').add(option);showCustomer()}else{state.items.unshift(saved);addLine(saved)}close();toast(`${type[0].toUpperCase()+type.slice(1)} added`)}catch(err){toast(err.message)}}};
  const showCustomer=()=>{const c=state.customers.find(x=>x.id==$('#invoiceCustomer').value);$('#customerInfo').innerHTML=c?`<b>${esc(c.business_name||c.name)}</b><span>${esc(c.address||'')}</span>${c.gstin?`<span>GSTIN: ${esc(c.gstin)}</span>`:''}`:''};
  addLine();$('#addExisting').onclick=()=>addLine();$('#newItem').onclick=()=>quickForm('item');$('#newCustomer').onclick=()=>quickForm('customer');$('#invoiceCustomer').onchange=showCustomer;$('#pageGst').onchange=calc;$('#invoiceBack').onclick=$('#cancelInvoice').onclick=()=>show('invoices');
  $('#invoiceCreate').onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(e.target));const customer=state.customers.find(c=>c.id==fd.customer_id);const invoiceLines=$$('.invoice-item-row',lines).map(r=>{const it=state.items.find(i=>i.id==$('.item',r).value);return{item_id:it?.id,name:it?.name,description:$('.description',r).value,quantity:+$('.qty',r).value,price:+$('.price',r).value,gst_rate:gstRate}});try{const inv=await api('/invoices',{method:'POST',body:{...fd,company_id:customer?.company_id,customer_id:+fd.customer_id,gst_enabled:$('#pageGst').checked,lines:invoiceLines}});await loadAll();preview(inv.id);toast('Invoice created')}catch(err){toast(err.message)}};
}

function invoiceForm(){return invoicePage()}

async function preview(id){const x=await api('/invoices/'+id),gstRate=x.lines[0]?.gst_rate||state.settings.gst_rate||18;modal(`<div class="sendbar"><button class="secondary" id="downloadPdf">⇩ Download PDF</button><button class="secondary" id="email">Email</button><button class="primary" id="whatsapp">Send WhatsApp</button><select id="status"><option value="draft">Draft</option><option value="sent">Sent</option><option value="paid">Paid</option><option value="overdue">Overdue</option><option value="cancelled">Cancelled</option></select><button class="danger-button" data-invoice-delete="${x.id}">Delete invoice</button></div><article class="invoice-paper"><div class="paper-head"><div>${x.logo?`<img class="logo-preview" src="${esc(x.logo)}">`:''}<h2>${esc(x.company_name)}</h2><div>${esc(x.company_address||'')}</div><div>${esc(x.company_email||'')} ${esc(x.company_phone||'')}</div>${x.company_gstin?`<div>GSTIN: ${esc(x.company_gstin)}</div>`:''}</div><div class="paper-meta"><h1>INVOICE</h1><b>${esc(x.number)}</b><p>Date: ${esc(x.invoice_date)}<br>Due: ${esc(x.due_date)}</p></div></div><div class="paper-party"><div><small>BILL TO</small><h3>${esc(x.customer_business||x.customer_name)}</h3><div>${esc(x.customer_name)}</div><div>${esc(x.customer_address||'')}</div>${x.customer_gstin?`<div>GSTIN: ${esc(x.customer_gstin)}</div>`:''}</div><div>${x.po_number?`<small>PO NUMBER</small><p>${esc(x.po_number)}</p>`:''}</div></div><table class="paper-table"><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Amount</th></tr></thead><tbody>${x.lines.map(l=>`<tr><td><b>${esc(l.name)}</b><small><br>${esc(l.description||'')}</small></td><td>${l.quantity}</td><td>${money(l.price)}</td><td>${money(l.amount)}</td></tr>`).join('')}</tbody></table><div class="paper-total"><div><span>Subtotal</span><b>${money(x.subtotal)}</b></div>${x.gst_enabled?`<div><span>GST (${esc(gstRate)}%)</span><b>${money(x.tax_total)}</b></div>`:''}<div class="grand"><span>Total due</span><span>${money(x.total)}</span></div></div>${x.notes?`<h4>Notes</h4><p>${esc(x.notes)}</p>`:''}${x.bank_details?`<h4>Payment details</h4><p>${esc(x.bank_details)}</p>`:''}<footer class="invoice-footer">This is a computer-generated invoice and does not require a signature.</footer></article>`,true);$('#status').value=x.status;$('#status').onchange=async e=>{await api('/invoices/'+id,{method:'PATCH',body:{status:e.target.value}});await loadAll();toast('Status updated')};$('#downloadPdf').onclick=()=>{const old=document.title,safe=(x.customer_business||x.customer_name||'Invoice').replace(/[\\/:*?"<>|]/g,'-');document.title=`${safe} ${x.invoice_date}`;window.addEventListener('afterprint',()=>document.title=old,{once:true});window.print()};$('#email').onclick=()=>{location.href=`mailto:${encodeURIComponent(x.customer_email||'')}?subject=${encodeURIComponent('Invoice '+x.number)}&body=${encodeURIComponent(`Hello ${x.customer_name},\n\nYour invoice ${x.number} for ${money(x.total)} is ready.\n\nRegards,\n${x.company_name}`)}`};$('#whatsapp').onclick=async()=>{try{await api(`/invoices/${id}/whatsapp`,{method:'POST'});toast('WhatsApp sent');await loadAll()}catch(e){toast(e.message)}}}

function estimatePage(){invoicePage();state.page='create-estimate';$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page==='estimates'));$('#pageTitle').textContent='Create estimate';$('#pageHint').textContent='Prepare a quotation for your customer';$('#invoiceBack').textContent='‹ Back to estimates';$('#invoiceBack').onclick=$('#cancelInvoice').onclick=()=>show('estimates');const dateInput=$('[name="invoice_date"]');dateInput.name='estimate_date';dateInput.closest('label').childNodes[0].textContent='Estimate date *';$('.gst-option small').textContent='Calculate GST on the estimate subtotal';const form=$('#invoiceCreate');form.onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(form)),customer=state.customers.find(c=>c.id==fd.customer_id),gstRate=Number(state.settings.gst_rate||18),lines=$$('.invoice-item-row').map(r=>{const it=state.items.find(i=>i.id==$('.item',r).value);return{item_id:it?.id,name:it?.name,description:$('.description',r).value,quantity:+$('.qty',r).value,price:+$('.price',r).value,gst_rate:gstRate}});try{const result=await api('/estimates',{method:'POST',body:{...fd,company_id:customer?.company_id,customer_id:+fd.customer_id,gst_enabled:$('#pageGst').checked,lines}});await loadAll();estimatePreview(result.id);toast('Estimate created')}catch(err){toast(err.message)}}}

function estimatesPage(){const data=state.estimates;$('#content').innerHTML=`<div class="panel"><div class="toolbar"><input id="estimateSearch" placeholder="Search estimates..."><span>${data.length} total</span></div>${data.length?`<div class="table-wrap"><table><thead><tr><th>Estimate</th><th>Customer</th><th>Company</th><th>Date</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody>${data.map(x=>`<tr><td><b>${esc(x.number)}</b></td><td>${esc(x.customer)}</td><td>${esc(x.company)}</td><td>${esc(x.estimate_date)}</td><td>${money(x.total)}</td><td><span class="badge ${x.status}">${esc(x.status)}</span></td><td class="actions"><button data-estimate-view="${x.id}">View</button><button class="danger-link" data-estimate-delete="${x.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No estimates yet.</div>'}</div>`;$('#estimateSearch').oninput=e=>$$('#content tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));$$('[data-estimate-view]').forEach(b=>b.onclick=()=>estimatePreview(b.dataset.estimateView));$$('[data-estimate-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this estimate?')){await api('/estimates/'+b.dataset.estimateDelete,{method:'DELETE'});await loadAll();estimatesPage();toast('Estimate deleted')}})}

async function estimatePreview(id){const x=await api('/estimates/'+id),rate=x.lines[0]?.gst_rate||state.settings.gst_rate||18;modal(`<div class="sendbar"><a class="secondary download-link" href="/api/estimates/${id}/pdf" download>⇩ Download PDF</a><button class="primary" id="estimateWhatsapp">Send WhatsApp</button><select id="estimateStatus"><option value="draft">Draft</option><option value="sent">Sent</option><option value="accepted">Accepted</option><option value="rejected">Rejected</option><option value="expired">Expired</option></select></div><article class="invoice-paper"><div class="paper-head"><div>${x.logo?`<img class="logo-preview" src="${esc(x.logo)}">`:''}<h2>${esc(x.company_name)}</h2><div>${esc(x.company_address||'')}</div></div><div class="paper-meta"><h1>ESTIMATE</h1><b>${esc(x.number)}</b><p>Date: ${esc(x.estimate_date)}<br>Valid until: ${esc(x.due_date)}</p></div></div><div class="paper-party"><div><small>PREPARED FOR</small><h3>${esc(x.customer_business||x.customer_name)}</h3><div>${esc(x.customer_address||'')}</div></div></div><table class="paper-table"><thead><tr><th>Item</th><th>Qty</th><th>Price</th><th>Amount</th></tr></thead><tbody>${x.lines.map(l=>`<tr><td><b>${esc(l.name)}</b><small><br>${esc(l.description||'')}</small></td><td>${l.quantity}</td><td>${money(l.price)}</td><td>${money(l.amount)}</td></tr>`).join('')}</tbody></table><div class="paper-total"><div><span>Subtotal</span><b>${money(x.subtotal)}</b></div>${x.gst_enabled?`<div><span>GST (${esc(rate)}%)</span><b>${money(x.tax_total)}</b></div>`:''}<div class="grand"><span>Estimate total</span><span>${money(x.total)}</span></div></div>${x.notes?`<h4>Notes</h4><p>${esc(x.notes)}</p>`:''}<footer class="invoice-footer">This is a computer-generated estimate and does not require a signature.</footer></article>`,true);$('#estimateStatus').value=x.status;$('#estimateStatus').onchange=async e=>{await api('/estimates/'+id,{method:'PATCH',body:{status:e.target.value}});await loadAll();toast('Status updated')};$('#estimateWhatsapp').onclick=async()=>{try{await api(`/estimates/${id}/whatsapp`,{method:'POST'});toast('Estimate sent on WhatsApp');await loadAll()}catch(err){toast(err.message)}}}

async function ledgerPage(){const data=await api('/ledger');const totals=data.reduce((a,x)=>({invoiced:a.invoiced+x.invoiced,paid:a.paid+x.paid}),{invoiced:0,paid:0});$('#content').innerHTML=`<div class="cards ledger-cards"><div class="card metric"><div><p>Total invoiced</p><h3>${money(totals.invoiced)}</h3></div><i>▤</i></div><div class="card metric"><div><p>Total received</p><h3>${money(totals.paid)}</h3></div><i>✓</i></div><div class="card metric"><div><p>Total pending</p><h3>${money(totals.invoiced-totals.paid)}</h3></div><i>₹</i></div></div><div class="panel"><div class="toolbar"><input id="ledgerSearch" placeholder="Search customer..."><span>${data.length} customers</span></div>${data.length?`<div class="table-wrap"><table id="ledgerTable"><thead><tr><th>Customer</th><th>Company</th><th>Invoiced</th><th>Paid</th><th>Pending</th><th></th></tr></thead><tbody>${data.map(x=>`<tr><td><b>${esc(x.business_name||x.name)}</b><small class="cell-sub">${esc(x.phone||'')}</small></td><td>${esc(x.company)}</td><td>${money(x.invoiced)}</td><td class="received">${money(x.paid)}</td><td class="${x.invoiced-x.paid>0?'pending':''}">${money(x.invoiced-x.paid)}</td><td class="actions ledger-actions"><button data-statement="${x.id}">Statement</button><button data-payment="${x.id}">＋ Payment</button>${x.invoiced-x.paid>0?`<button data-reminder="${x.id}">Reminder</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No customers in ledger yet.</div>'}</div>`;$('#ledgerSearch').oninput=e=>$$('#ledgerTable tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));$$('[data-statement]').forEach(b=>b.onclick=()=>ledgerStatement(b.dataset.statement));$$('[data-payment]').forEach(b=>b.onclick=()=>paymentForm(b.dataset.payment));$$('[data-reminder]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api(`/customers/${b.dataset.reminder}/reminder`,{method:'POST'});toast('Pending payment reminder sent')}catch(e){toast(e.message)}finally{b.disabled=false}})}

async function paymentForm(customerId){const ledger=await api(`/customers/${customerId}/ledger`);const open=ledger.invoices.filter(x=>x.total-x.paid>0);modal(`<h2>Add payment</h2><p>${esc(ledger.customer.business_name||ledger.customer.name)} · Pending ${money(ledger.total_invoiced-ledger.total_paid)}</p><form id="paymentForm"><div class="form-grid"><label>Invoice (optional)<select name="invoice_id"><option value="">General / advance payment</option>${open.map(i=>`<option value="${i.id}">${esc(i.number)} — pending ${money(i.total-i.paid)}</option>`).join('')}</select></label>${field('Amount received *','amount','','number','required min="0.01" step="0.01"')}${field('Payment date *','payment_date',today(),'date','required')}<label>Payment mode<select name="mode"><option value="bank">Bank transfer</option><option value="cash">Cash</option><option value="upi">UPI</option><option value="card">Card</option><option value="cheque">Cheque</option><option value="other">Other</option></select></label>${field('Reference / transaction ID','reference')}<label class="full">Note<textarea name="note"></textarea></label><label class="full switch"><input type="checkbox" name="send_whatsapp" checked><span>Send WhatsApp payment receipt automatically</span></label></div><div class="form-actions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary">Save payment</button></div></form>`);$('#paymentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=Object.fromEntries(f);b.customer_id=+customerId;b.company_id=ledger.customer.company_id;b.invoice_id=b.invoice_id?+b.invoice_id:null;b.amount=+b.amount;b.send_whatsapp=f.has('send_whatsapp');try{const result=await api('/payments',{method:'POST',body:b});close();await ledgerPage();toast(result.whatsapp?.sent?'Payment saved & WhatsApp sent':`Payment saved${result.whatsapp?.warning?' · '+result.whatsapp.warning:''}`)}catch(err){toast(err.message)}}}

async function ledgerStatement(customerId){const x=await api(`/customers/${customerId}/ledger`);modal(`<h2>${esc(x.customer.business_name||x.customer.name)} — Ledger</h2><div class="ledger-summary"><div><small>Total invoiced</small><b>${money(x.total_invoiced)}</b></div><div><small>Total paid</small><b>${money(x.total_paid)}</b></div><div><small>Pending</small><b>${money(x.total_invoiced-x.total_paid)}</b></div></div><h3>Invoices</h3><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Date</th><th>Total</th><th>Paid</th><th>Pending</th></tr></thead><tbody>${x.invoices.map(i=>`<tr><td>${esc(i.number)}</td><td>${esc(i.invoice_date)}</td><td>${money(i.total)}</td><td>${money(i.paid)}</td><td>${money(i.total-i.paid)}</td></tr>`).join('')||'<tr><td colspan="5">No invoices</td></tr>'}</tbody></table></div><h3>Payment history</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Invoice</th><th>Mode</th><th>Reference</th><th>Amount</th></tr></thead><tbody>${x.payments.map(p=>`<tr><td>${esc(p.payment_date)}</td><td>${esc(p.invoice_number||'General')}</td><td>${esc(p.mode)}</td><td>${esc(p.reference||'—')}</td><td class="received">${money(p.amount)}</td></tr>`).join('')||'<tr><td colspan="5">No payments received</td></tr>'}</tbody></table></div><div class="form-actions"><button class="secondary" data-close>Close</button><button class="primary" id="statementPayment">＋ Add payment</button></div>`,true);$('#statementPayment').onclick=()=>{close();paymentForm(customerId)}}

async function followupsPage(){const data=await api('/followups'),todayValue=today();$('#content').innerHTML=`<div class="panel"><div class="toolbar"><input id="followupSearch" placeholder="Search follow-ups..."><span>${data.filter(x=>x.status==='pending').length} pending</span></div>${data.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Message</th><th>Last sent</th><th>Status</th><th></th></tr></thead><tbody>${data.map(x=>`<tr class="${x.status==='pending'&&x.followup_date<=todayValue?'followup-due':''}"><td>${esc(x.followup_date)}</td><td><b>${esc(x.business_name||x.customer)}</b><small class="cell-sub">${esc(x.phone||'')}</small></td><td>${esc(x.message)}</td><td>${esc(x.last_sent_at||'Not sent')}</td><td><span class="badge ${x.status}">${esc(x.status)}</span></td><td class="actions followup-actions">${x.status==='pending'?`<button data-followup-send="${x.id}">Send WhatsApp</button><button data-followup-done="${x.id}">Complete</button>`:''}<button class="danger-link" data-followup-delete="${x.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No follow-ups scheduled.</div>'}</div>`;$('#followupSearch').oninput=e=>$$('#content tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase()));$$('[data-followup-send]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api(`/followups/${b.dataset.followupSend}/send`,{method:'POST'});toast('Follow-up sent on WhatsApp');followupsPage()}catch(err){toast(err.message)}finally{b.disabled=false}});$$('[data-followup-done]').forEach(b=>b.onclick=async()=>{await api('/followups/'+b.dataset.followupDone,{method:'PATCH',body:{status:'completed'}});followupsPage();toast('Follow-up completed')});$$('[data-followup-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this follow-up?')){await api('/followups/'+b.dataset.followupDelete,{method:'DELETE'});followupsPage();toast('Follow-up deleted')}})}

function followupForm(){modal(`<h2>Schedule follow-up</h2><form id="followupForm"><div class="form-grid"><label>Customer *<select name="customer_id" required><option value="">Select customer</option>${state.customers.map(c=>`<option value="${c.id}">${esc(c.business_name||c.name)}</option>`).join('')}</select></label>${field('Follow-up date *','followup_date',today(),'date','required')}<label class="full">WhatsApp message *<textarea name="message" rows="5" required placeholder="Just checking in regarding our estimate. Please let us know if you have any questions."></textarea></label></div><div class="form-actions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary">Save follow-up</button></div></form>`);$('#followupForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.customer_id=+b.customer_id;try{await api('/followups',{method:'POST',body:b});close();followupsPage();toast('Follow-up scheduled')}catch(err){toast(err.message)}}}

const automationEvents=[['invoice_created','Invoice Created','{{1}} Customer, {{2}} Invoice no., {{3}} Amount, {{4}} Date, {{5}} Due date, {{6}} Company'],['estimate_created','Estimate Created','{{1}} Customer, {{2}} Estimate no., {{3}} Amount, {{4}} Valid until, {{5}} Company'],['estimate_followup','Estimate Daily Follow-up','{{1}} Customer, {{2}} Estimate no., {{3}} Amount, {{4}} Company'],['payment_reminder','Payment Reminder','{{1}} Customer, {{2}} Pending amount, {{3}} Company'],['payment_received','Payment Received','{{1}} Customer, {{2}} Amount, {{3}} Date, {{4}} Reference, {{5}} Balance, {{6}} Company']];
async function automationsPage(){let templates=[],loadError='';try{const result=await api('/meta/templates');templates=result.data||[]}catch(e){loadError=e.message}const approved=templates.filter(t=>t.status==='APPROVED');$('#content').innerHTML=`${loadError?`<div class="automation-alert"><div><b>Connect Meta template manager</b><p>${esc(loadError)}</p></div><button class="primary" id="openMetaSettings">Open Settings</button></div>`:''}<div class="automation-toolbar"><div><h3>Message template library</h3><p>Create templates in CRM and submit them directly to Meta for approval.</p></div><div><button class="secondary" id="syncTemplates">↻ Sync Meta</button><button class="primary" id="createTemplate">＋ Create template</button></div></div><div class="automation-layout"><section class="panel template-library"><div class="panel-head"><h3>Meta templates</h3><span>${templates.length} templates</span></div>${templates.length?`<div class="template-grid">${templates.map(t=>`<article class="template-card"><div><b>${esc(t.name)}</b><span class="template-status ${String(t.status).toLowerCase()}">${esc(t.status)}</span></div><p>${esc(t.category)} · ${esc(t.language)}</p><small>${esc(t.components?.find(c=>c.type==='BODY')?.text||'')}</small><button class="danger-link" data-meta-delete="${esc(t.name)}">Delete</button></article>`).join('')}</div>`:'<div class="empty">No Meta templates loaded.</div>'}</section><section class="panel assignment-panel"><div class="panel-head"><div><h3>Automation assignments</h3><p>Only approved templates are available.</p></div></div><form id="assignmentForm">${automationEvents.map(([key,label,vars])=>`<label>${label}<select name="wa_template_${key}"><option value="" data-language="en">Free-text fallback (testing only)</option>${approved.map(t=>`<option value="${esc(t.name)}" data-language="${esc(t.language)}" ${state.settings[`wa_template_${key}`]===t.name&&(!state.settings[`wa_language_${key}`]||state.settings[`wa_language_${key}`]===t.language)?'selected':''}>${esc(t.name)} · ${esc(t.language)}</option>`).join('')}</select><small>${vars}</small><input type="hidden" name="wa_language_${key}" value="${esc(state.settings[`wa_language_${key}`]||approved.find(t=>t.name===state.settings[`wa_template_${key}`])?.language||'en')}"></label>`).join('')}<button class="primary">Save assignments</button></form></section></div>`;$('#openMetaSettings')?.addEventListener('click',()=>show('settings'));$('#syncTemplates').onclick=()=>automationsPage();$('#createTemplate').onclick=templateCreateForm;$('#assignmentForm').onsubmit=async e=>{e.preventDefault();e.target.querySelectorAll('select[name^="wa_template_"]').forEach(select=>{const key=select.name.replace('wa_template_','');const language=e.target.querySelector(`[name="wa_language_${key}"]`);if(language)language.value=select.options[select.selectedIndex]?.dataset.language||'en'});const values=Object.fromEntries(new FormData(e.target));await api('/settings/save',{method:'POST',body:values});state.settings={...state.settings,...values};toast('Automation templates assigned')};$$('[data-meta-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(`Delete Meta template ${b.dataset.metaDelete}?`))return;try{await api('/meta/templates?name='+encodeURIComponent(b.dataset.metaDelete),{method:'DELETE'});toast('Template deleted from Meta');automationsPage()}catch(err){toast(err.message)}})}

function templateCreateForm(){modal(`<h2>Create WhatsApp template</h2><p>Submitting creates the template in Meta and starts its approval review.</p><form id="metaTemplateForm"><div class="form-grid">${field('Template name *','name','','text','required pattern="[a-z0-9_]+" placeholder="invoice_created"')}<label>Category<select name="category"><option value="UTILITY">Utility</option><option value="MARKETING">Marketing</option><option value="AUTHENTICATION">Authentication</option></select></label>${field('Language code *','language','en','text','required')} ${field('Header text (optional)','header')}<label class="full">Message body *<textarea name="body" rows="8" required placeholder="Hello {{1}}, your invoice {{2}} for Rs. {{3}} is ready."></textarea></label><label class="full">Sample variable values *<input name="body_examples" required placeholder="Gagandeep, INV-0001, 1000.00"><small>Comma-separated, one sample for every variable in order.</small></label>${field('Footer (optional)','footer','Thank you')}</div><div class="form-actions"><button type="button" class="secondary" data-close>Cancel</button><button class="primary">Submit to Meta</button></div></form>`);$('#metaTemplateForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.body_examples=b.body_examples.split(',').map(x=>x.trim());b.header_examples=[];try{await api('/meta/templates',{method:'POST',body:b});close();toast('Template submitted to Meta review');automationsPage()}catch(err){toast(err.message)}}}

async function reportsPage(){const year=new Date().getFullYear(),defaultFrom=`${year}-01-01`;$('#content').innerHTML=`<div class="panel report-filter"><form id="reportFilters"><label>From<input type="date" name="from" value="${defaultFrom}"></label><label>To<input type="date" name="to" value="${today()}"></label><label>Customer<select name="customer_id"><option value="">All customers</option>${state.customers.map(c=>`<option value="${c.id}">${esc(c.business_name||c.name)}</option>`).join('')}</select></label><label>Company<select name="company_id"><option value="">All companies</option>${state.companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><button class="primary">Apply filters</button></form></div><div id="reportResults"></div>`;const load=async()=>{const f=new FormData($('#reportFilters')),query=new URLSearchParams([...f].filter(([,v])=>v));const d=await api('/reports?'+query);renderReports(d)};$('#reportFilters').onsubmit=e=>{e.preventDefault();load()};await load()}

function renderReports(d){const card=(title,value,icon)=>`<div class="card metric"><div><p>${title}</p><h3>${money(value)}</h3></div><i>${icon}</i></div>`;$('#reportResults').innerHTML=`<div class="cards report-cards">${card('Total invoiced',d.summary.invoiced,'▤')}${card('Payments received',d.summary.paid,'✓')}${card('Pending',d.summary.invoiced-d.summary.paid,'₹')}${card('GST collected',d.summary.gst,'%')}</div><div class="panel"><div class="panel-head"><h3>Invoice report</h3><button class="secondary" data-csv="invoices">Export CSV</button></div>${d.invoices.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Invoice</th><th>Client</th><th>Company</th><th>Taxable</th><th>GST</th><th>Total</th><th>Status</th></tr></thead><tbody>${d.invoices.map(x=>`<tr><td>${esc(x.invoice_date)}</td><td>${esc(x.number)}</td><td>${esc(x.business_name||x.customer)}</td><td>${esc(x.company)}</td><td>${money(x.subtotal)}</td><td>${money(x.tax_total)}</td><td>${money(x.total)}</td><td><span class="badge ${x.status}">${esc(x.status)}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No invoices in this period.</div>'}</div><div class="panel"><div class="panel-head"><h3>Payment report</h3><button class="secondary" data-csv="payments">Export CSV</button></div>${d.payments.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Client</th><th>Invoice</th><th>Mode</th><th>Reference</th><th>Amount</th></tr></thead><tbody>${d.payments.map(x=>`<tr><td>${esc(x.payment_date)}</td><td>${esc(x.business_name||x.customer)}</td><td>${esc(x.invoice_number||'General')}</td><td>${esc(x.mode)}</td><td>${esc(x.reference||'—')}</td><td class="received">${money(x.amount)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No payments in this period.</div>'}</div><div class="panel"><div class="panel-head"><h3>Client-wise report</h3><button class="secondary" data-csv="clients">Export CSV</button></div>${d.clients.length?`<div class="table-wrap"><table><thead><tr><th>Client</th><th>Company</th><th>Invoiced</th><th>Paid</th><th>Pending</th><th>GST</th></tr></thead><tbody>${d.clients.map(x=>`<tr><td><b>${esc(x.customer)}</b></td><td>${esc(x.company)}</td><td>${money(x.invoiced)}</td><td class="received">${money(x.paid)}</td><td class="pending">${money(x.invoiced-x.paid)}</td><td>${money(x.tax)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No client activity in this period.</div>'}</div><div class="panel gst-report"><div class="panel-head"><h3>GST Tax Report</h3><button class="secondary" data-csv="gst">Export CSV</button></div><div class="gst-summary"><div><span>Taxable sales</span><b>${money(d.summary.taxable)}</b></div><div><span>GST collected</span><b>${money(d.summary.gst)}</b></div><div><span>Total including GST</span><b>${money(d.summary.invoiced)}</b></div></div></div>`;const csvData={invoices:[['Date','Invoice','Client','Company','Taxable','GST','Total','Status'],...d.invoices.map(x=>[x.invoice_date,x.number,x.business_name||x.customer,x.company,x.subtotal,x.tax_total,x.total,x.status])],payments:[['Date','Client','Invoice','Mode','Reference','Amount'],...d.payments.map(x=>[x.payment_date,x.business_name||x.customer,x.invoice_number||'General',x.mode,x.reference,x.amount])],clients:[['Client','Company','Invoiced','Paid','Pending','GST'],...d.clients.map(x=>[x.customer,x.company,x.invoiced,x.paid,x.invoiced-x.paid,x.tax])],gst:[['Period From','Period To','Taxable Sales','GST Collected','Total Including GST'],[d.from,d.to,d.summary.taxable,d.summary.gst,d.summary.invoiced]]};$$('[data-csv]').forEach(b=>b.onclick=()=>downloadCsv(`${b.dataset.csv}-report-${d.from}-to-${d.to}.csv`,csvData[b.dataset.csv]))}

function downloadCsv(filename,rows){const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}

async function settings(){const s=await api('/settings');$('#content').innerHTML=`<form id="settingsForm"><div class="panel"><h3>CRM branding</h3><p>Change the CRM name shown in the sidebar and browser title.</p><div class="form-grid">${field('CRM name','crm_name',s.crm_name||'BillFlow','text','maxlength="60"')}</div></div><div class="panel"><h3>Tax settings</h3><p>This GST rate is applied once to the complete invoice subtotal when GST is enabled.</p><div class="form-grid">${field('Default GST rate %','gst_rate',s.gst_rate||18,'number','min="0" max="100" step="0.01"')}</div></div><div class="panel"><h3>Automatic estimate follow-up</h3><p>When an estimate is sent or marked Sent, a pending follow-up is created automatically.</p><div class="form-grid">${field('Follow up after days','estimate_followup_days',s.estimate_followup_days||3,'number','min="1" max="90" step="1"')}</div></div><div class="panel"><h3>Meta WhatsApp Cloud API</h3><p>Credentials are stored on this server and used to send invoice messages.</p><div class="form-grid">${field('Phone number ID','meta_phone_id',s.meta_phone_id)}${field('Permanent access token','meta_token',s.meta_token,'password')} ${field('Graph API version','meta_api_version',s.meta_api_version||'v22.0')}</div></div><div class="panel"><h3>Email settings</h3><p>Email button opens your default email application. SMTP delivery can be connected here in the next deployment phase.</p><div class="form-grid">${field('Reply-to email','reply_email',s.reply_email,'email')}${field('Default email subject','email_subject',s.email_subject||'Your invoice is ready')}</div></div><div class="form-actions"><button class="primary">Save settings</button></div></form>`;const form=$('#settingsForm');form.elements.crm_name.oninput=e=>{state.settings.crm_name=e.target.value;applyBrand()};form.onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));await api('/settings/save',{method:'POST',body:values});state.settings={...state.settings,...values};applyBrand();toast('Settings saved')}}
init();
